import java.util.Scanner;
public class PythagoreanTheorem2 {
	public static void main(String[] args) {
		//Paso 1: Recibir los valores para el primer lado de un triangulo rectangulo y la hipotenusa
		Scanner scan = new Scanner(System.in);
		System.out.println("Ingrese la longitud del lado A:");
		double sideA = scan.nextDouble();
		System.out.println("Ingrese la longitud de la hipotenusa:");
		double hypotenuse = scan.nextDouble();
		scan.close();
		//Paso 2: Calcular el cuadrado del lado A
		double squareSideA = Math.pow(sideA, 2);
		//Paso 3: Calcular el cuadrado de la hipotenusa
		double squareHypotenuse = Math.pow(hypotenuse, 2);
		//Paso 4: Usar el teorema de Pitagoras para calcular la longitud del otro lado adyacente del triangulo
		double sideB = Math.sqrt(squareHypotenuse - squareSideA);
		//Paso 4: Imprimir el resultado
		System.out.println("Dado que el lado A es " + sideA + " y la hipotenusa es " + hypotenuse + ", el lado B es " + sideB);
	}
}

